#!/usr/bin/env python3
"""Writes gt_proto_a.caspien (stdlib/gt_set, the id-less hash set) and gt_proto_e.caspien (stdlib, design E): the same register / alive / moved
workload on GT_N synthetic addresses in pseudo-random order; the E program adds the id operations. Prints ns per operation (CPU time via clock())."""
import os
HEAD = '''// Ghost-table micro benchmark ({which}). GT_N synthetic addresses 48 bytes apart in one malloc'd region, visited in a pseudo-random order
// (k = i * 7919 mod N, N prime-ish). Generated by make_proto_bench.py.
import "../../stdlib/libc.caspien"
{imports}
extern getenv(static imut string) static imut string
extern atol(static imut string) mut u64

func lap(name: static imut string, t0: mut u64, ops: mut u64) mut u64{{
	let t1 = mut 0
	unsafe assume extern{{
		assume match ops != 0
		t1 = clock()
		printf("%-28s %6llu ns/op\\n", name, (t1 - t0) * 1000 / ops)
		t1 = clock()
	}}
	return t1
}}

func main() void{{
	unsafe assume extern{{
		let n = mut atol(getenv("GT_N"))
		assume match n != 0
		let:<raw mut u8> region = null
		region = mut malloc(n * 48 + 64)
		gt_init()
		let t = mut clock()
		for i in 0..n{{
			let k = mut ((i * 7919) % n)
			let p = mut (region + k * 48)
			let ok = gt_register(p)
		}}
		t = lap("register", t, n)
		let hits = mut 0
		for i in 0..n{{
			let k = mut ((i * 7919) % n)
			let p = mut (region + k * 48)
			let alive = gt_alive_check(p)
			if alive{{ hits += 1 }}
		}}
		t = lap("alive_check (hit)", t, n)
{idops}
		for i in 0..n{{
			let k = mut ((i * 7919) % n)
			let p = mut (region + k * 48)
			gt_moved(p)
		}}
		t = lap("moved (unregister)", t, n)
		printf("hits %llu\\n", hits)
		free(region)
	}}
}}
'''
IDOPS = '''		let sum = mut 0
		for i in 0..n {
			let k = mut ((i * 7919) % n)
			let p = mut (region + k * 48)
			sum += gt_ref_id(p)
		}
		t = lap("ref_id (first, creates id)", t, n)
		for i in 0..n {
			let k = mut ((i * 7919) % n)
			let p = mut (region + k * 48)
			sum += gt_ref_id(p)
		}
		t = lap("ref_id (again)", t, n)
		let found = mut 0
		for i in 0..n {
			let id = mut (i + 1)
			let q = mut gt_ref_resolve(id)
			if q != null{ found += 1 }
		}
		t = lap("ref_resolve (live id)", t, n)
		printf("ids %llu found %llu\\n", sum, found)
'''
A = '''import "../../stdlib/gt_set/gt_init.caspien"
import "../../stdlib/gt_set/gt_register.caspien"
import "../../stdlib/gt_set/gt_alive_check.caspien"
import "../../stdlib/gt_set/gt_destruct.caspien"
import "../../stdlib/gt_set/gt_moved.caspien"'''
E = '''import "../../stdlib/gt_init.caspien"
import "../../stdlib/gt_register.caspien"
import "../../stdlib/gt_alive_check.caspien"
import "../../stdlib/gt_destruct.caspien"
import "../../stdlib/gt_moved.caspien"
import "../../stdlib/gt_ref_id.caspien"
import "../../stdlib/gt_ref_resolve.caspien"'''
d = os.path.dirname(os.path.abspath(__file__))
open(os.path.join(d, 'gt_proto_a.caspien'), 'w').write(HEAD.format(which='A: current table', imports=A, idops=''))
open(os.path.join(d, 'gt_proto_z.caspien'), 'w').write(HEAD.format(which='E tables, no id ever taken', imports=E, idops=''))
open(os.path.join(d, 'gt_proto_e.caspien'), 'w').write(HEAD.format(which='E: tagged set + id tables', imports=E, idops=IDOPS))
